(async()=>{const s=window.keepfallScene;const m=await import('/src/scene/layout.ts');const out=[];const B=/^(house|tower|barracks|archery)/;
for(const L of [1,2,3,4]){const items=[];
for(const t of ['farm','lumberCamp','mine','forge']){for(const p of m.SITES[t].parts(L)){if(!B.test(p.key))continue;const f=s.textures.getFrame(p.key);const w=f.realWidth*(p.scale??1),h=f.realHeight*(p.scale??1);items.push({t,k:p.key,x:p.x,y:p.y,l:p.x-w*0.36,r:p.x+w*0.36,top:p.y-h*0.62,b:p.y});}}
items.push({t:'castle',k:'castle',x:512,y:430,l:340,r:690,top:236,b:470});
for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i],b=items[j];const ox=Math.min(a.r,b.r)-Math.max(a.l,b.l),oy=Math.min(a.b,b.b)-Math.max(a.top,b.top);if(ox>6&&oy>6)out.push('L'+L+' '+a.t+'/'+a.k+'@'+a.x+','+a.y+' x '+b.t+'/'+b.k+'@'+b.x+','+b.y+' ['+Math.round(ox)+'x'+Math.round(oy)+']');}
for(const a of items){if(a.t==='castle')continue;if(a.l<130||a.r>894||a.b>648||a.top<122)out.push('L'+L+' wall '+a.t+'/'+a.k+'@'+a.x+','+a.y+' box '+Math.round(a.l)+'-'+Math.round(a.r)+' y'+Math.round(a.top)+'-'+a.b);}}
return out.join(' | ')})()
